#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum Expr<'t> {
    LiteralExpr(LiteralExpr<'t>),
    NameExpr(NameExpr<'t>),
    ThisExpr(ThisExpr<'t>),
    SuperExpr(SuperExpr<'t>),
    ParenExpr(ParenExpr<'t>),
    ClassLiteralExpr(ClassLiteralExpr<'t>),
    FieldAccessExpr(FieldAccessExpr<'t>),
    ArrayAccessExpr(ArrayAccessExpr<'t>),
    MethodCallExpr(MethodCallExpr<'t>),
    ConstructorCallExpr(ConstructorCallExpr<'t>),
    NewExpr(NewExpr<'t>),
    ArrayCreationExpr(ArrayCreationExpr<'t>),
    PrefixExpr(PrefixExpr<'t>),
    PostfixExpr(PostfixExpr<'t>),
    BinaryExpr(BinaryExpr<'t>),
    InstanceofExpr(InstanceofExpr<'t>),
    ConditionalExpr(ConditionalExpr<'t>),
    AssignExpr(AssignExpr<'t>),
    CastExpr(CastExpr<'t>),
    LambdaExpr(LambdaExpr<'t>),
    MethodRefExpr(MethodRefExpr<'t>),
    SwitchExpr(SwitchExpr<'t>),
}

impl<'t> AstNode<'t> for Expr<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::LiteralExpr
                | SyntaxKind::NameExpr
                | SyntaxKind::ThisExpr
                | SyntaxKind::SuperExpr
                | SyntaxKind::ParenExpr
                | SyntaxKind::ClassLiteralExpr
                | SyntaxKind::FieldAccessExpr
                | SyntaxKind::ArrayAccessExpr
                | SyntaxKind::MethodCallExpr
                | SyntaxKind::ConstructorCallExpr
                | SyntaxKind::NewExpr
                | SyntaxKind::ArrayCreationExpr
                | SyntaxKind::PrefixExpr
                | SyntaxKind::PostfixExpr
                | SyntaxKind::BinaryExpr
                | SyntaxKind::InstanceofExpr
                | SyntaxKind::ConditionalExpr
                | SyntaxKind::AssignExpr
                | SyntaxKind::CastExpr
                | SyntaxKind::LambdaExpr
                | SyntaxKind::MethodRefExpr
                | SyntaxKind::SwitchExpr
        )
    }

    fn cast(node: SyntaxNode<'t>) -> Option<Self> {
        let kind = node.kind();
        if LiteralExpr::can_cast(kind) {
            return LiteralExpr::cast(node).map(Expr::LiteralExpr);
        }
        if NameExpr::can_cast(kind) {
            return NameExpr::cast(node).map(Expr::NameExpr);
        }
        if ThisExpr::can_cast(kind) {
            return ThisExpr::cast(node).map(Expr::ThisExpr);
        }
        if SuperExpr::can_cast(kind) {
            return SuperExpr::cast(node).map(Expr::SuperExpr);
        }
        if ParenExpr::can_cast(kind) {
            return ParenExpr::cast(node).map(Expr::ParenExpr);
        }
        if ClassLiteralExpr::can_cast(kind) {
            return ClassLiteralExpr::cast(node).map(Expr::ClassLiteralExpr);
        }
        if FieldAccessExpr::can_cast(kind) {
            return FieldAccessExpr::cast(node).map(Expr::FieldAccessExpr);
        }
        if ArrayAccessExpr::can_cast(kind) {
            return ArrayAccessExpr::cast(node).map(Expr::ArrayAccessExpr);
        }
        if MethodCallExpr::can_cast(kind) {
            return MethodCallExpr::cast(node).map(Expr::MethodCallExpr);
        }
        if ConstructorCallExpr::can_cast(kind) {
            return ConstructorCallExpr::cast(node).map(Expr::ConstructorCallExpr);
        }
        if NewExpr::can_cast(kind) {
            return NewExpr::cast(node).map(Expr::NewExpr);
        }
        if ArrayCreationExpr::can_cast(kind) {
            return ArrayCreationExpr::cast(node).map(Expr::ArrayCreationExpr);
        }
        if PrefixExpr::can_cast(kind) {
            return PrefixExpr::cast(node).map(Expr::PrefixExpr);
        }
        if PostfixExpr::can_cast(kind) {
            return PostfixExpr::cast(node).map(Expr::PostfixExpr);
        }
        if BinaryExpr::can_cast(kind) {
            return BinaryExpr::cast(node).map(Expr::BinaryExpr);
        }
        if InstanceofExpr::can_cast(kind) {
            return InstanceofExpr::cast(node).map(Expr::InstanceofExpr);
        }
        if ConditionalExpr::can_cast(kind) {
            return ConditionalExpr::cast(node).map(Expr::ConditionalExpr);
        }
        if AssignExpr::can_cast(kind) {
            return AssignExpr::cast(node).map(Expr::AssignExpr);
        }
        if CastExpr::can_cast(kind) {
            return CastExpr::cast(node).map(Expr::CastExpr);
        }
        if LambdaExpr::can_cast(kind) {
            return LambdaExpr::cast(node).map(Expr::LambdaExpr);
        }
        if MethodRefExpr::can_cast(kind) {
            return MethodRefExpr::cast(node).map(Expr::MethodRefExpr);
        }
        if SwitchExpr::can_cast(kind) {
            return SwitchExpr::cast(node).map(Expr::SwitchExpr);
        }
        None
    }

    fn syntax(self) -> SyntaxNode<'t> {
        match self {
            Expr::LiteralExpr(it) => it.syntax(),
            Expr::NameExpr(it) => it.syntax(),
            Expr::ThisExpr(it) => it.syntax(),
            Expr::SuperExpr(it) => it.syntax(),
            Expr::ParenExpr(it) => it.syntax(),
            Expr::ClassLiteralExpr(it) => it.syntax(),
            Expr::FieldAccessExpr(it) => it.syntax(),
            Expr::ArrayAccessExpr(it) => it.syntax(),
            Expr::MethodCallExpr(it) => it.syntax(),
            Expr::ConstructorCallExpr(it) => it.syntax(),
            Expr::NewExpr(it) => it.syntax(),
            Expr::ArrayCreationExpr(it) => it.syntax(),
            Expr::PrefixExpr(it) => it.syntax(),
            Expr::PostfixExpr(it) => it.syntax(),
            Expr::BinaryExpr(it) => it.syntax(),
            Expr::InstanceofExpr(it) => it.syntax(),
            Expr::ConditionalExpr(it) => it.syntax(),
            Expr::AssignExpr(it) => it.syntax(),
            Expr::CastExpr(it) => it.syntax(),
            Expr::LambdaExpr(it) => it.syntax(),
            Expr::MethodRefExpr(it) => it.syntax(),
            Expr::SwitchExpr(it) => it.syntax(),
        }
    }
}

