/// A qualifier that can be a type or an expression (decision 2).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum ExprOrType<'t> {
    Expr(Expr<'t>),
    Type(Type<'t>),
}

impl<'t> AstNode<'t> for ExprOrType<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind,
            SyntaxKind::LiteralExpr
                | SyntaxKind::NameExpr
                | SyntaxKind::ThisExpr
                | SyntaxKind::SuperExpr
                | SyntaxKind::ParenExpr
                | SyntaxKind::ClassLiteralExpr
                | SyntaxKind::FieldAccessExpr
                | SyntaxKind::ArrayAccessExpr
                | SyntaxKind::MethodCallExpr
                | SyntaxKind::ConstructorCallExpr
                | SyntaxKind::NewExpr
                | SyntaxKind::ArrayCreationExpr
                | SyntaxKind::PrefixExpr
                | SyntaxKind::PostfixExpr
                | SyntaxKind::BinaryExpr
                | SyntaxKind::InstanceofExpr
                | SyntaxKind::ConditionalExpr
                | SyntaxKind::AssignExpr
                | SyntaxKind::CastExpr
                | SyntaxKind::LambdaExpr
                | SyntaxKind::MethodRefExpr
                | SyntaxKind::SwitchExpr
                | SyntaxKind::PrimitiveType
                | SyntaxKind::ClassType
                | SyntaxKind::ArrayType
                | SyntaxKind::VoidType
                | SyntaxKind::IntersectionType
                | SyntaxKind::UnionType
        )
    }

    fn cast(node: SyntaxNode<'t>) -> Option<Self> {
        let kind = node.kind();
        if Expr::can_cast(kind) {
            return Expr::cast(node).map(ExprOrType::Expr);
        }
        if Type::can_cast(kind) {
            return Type::cast(node).map(ExprOrType::Type);
        }
        None
    }

    fn syntax(self) -> SyntaxNode<'t> {
        match self {
            ExprOrType::Expr(it) => it.syntax(),
            ExprOrType::Type(it) => it.syntax(),
        }
    }
}

impl<'t> From<Expr<'t>> for ExprOrType<'t> {
    fn from(node: Expr<'t>) -> ExprOrType<'t> {
        ExprOrType::Expr(node)
    }
}

impl<'t> From<Type<'t>> for ExprOrType<'t> {
    fn from(node: Type<'t>) -> ExprOrType<'t> {
        ExprOrType::Type(node)
    }
}

